mapper.select:
SELECT id, member_id, agreement_type, is_agreed, agreement_version, agreed_at
  FROM member_agreement
 WHERE member_id = #{memberId}
   AND agreement_type = #{type}

mapper.update:
UPDATE member_agreement
   SET is_agreed = #{agreed},
       agreed_at = NOW()
 WHERE member_id = #{memberId}
   AND agreement_type = #{type}
